def make_test(ystarts):
    out=[[3]*27 for _ in range(27)]
    pat=[[1,1,1],[4,4,2],[1,4,1],[8,0,0]]
    for i,row in enumerate(pat):
        for j,c in enumerate(row):
            if c:
                out[1+2*i][1+2*j]=c
                for r in range(ystarts[i],ystarts[i]+4):
                    for col in range(8+5*j,12+5*j): out[r][col]=c
    return out
g3=make_test([5,10,15,20])
print(json.dumps({'action':'submit','grid':g3}))
